/**
 * One-time fix: some image URLs in Postgres are stored as bare relative
 * paths (e.g. "/uploads/restaurants/restaurant-123-photo.jpg") instead of
 * a full URL. These were generated by the newer local upload routes
 * (POST /storage/upload, POST /storage/profilePictures/upload) which only
 * ever returned the relative path.
 *
 * This adds the domain prefix so they match the format of everything else:
 *   /uploads/restaurants/foo.jpg  ->  https://gourmetdamour.com/uploads/restaurants/foo.jpg
 *
 * Only rows that are relative (start with "/uploads/" and do NOT already
 * start with "http") are touched. Anything already a full URL, or NULL,
 * is left untouched.
 *
 * Run from inside your backend project (so it can reuse ./db.js's pool):
 *
 *   DRY_RUN mode (default — no changes made, just shows what would happen):
 *     node fix-relative-urls.js
 *
 *   Actually apply the changes:
 *     APPLY=true node fix-relative-urls.js
 */

const { pool } = require('./db.js');

const PUBLIC_BASE_URL = process.env.PUBLIC_BASE_URL || 'https://gourmetdamour.com';
const APPLY = process.env.APPLY === 'true';

const TARGETS = [
  { table: 'restaurants', column: 'image_url' },
  { table: 'menu_items', column: 'image_url' },
  { table: 'users', column: 'profile_picture' },
];

async function processTarget({ table, column }) {
  // Relative path = starts with "/" but not "http" (covers both http and https)
  const { rows } = await pool.query(
    `SELECT id, ${column} AS old_url FROM ${table}
     WHERE ${column} LIKE '/%' AND ${column} NOT ILIKE 'http%'`
  );

  console.log(`\n${table}.${column}: ${rows.length} row(s) to update`);

  if (rows.length === 0) return { table, column, count: 0 };

  for (const row of rows.slice(0, 5)) {
    const newUrl = `${PUBLIC_BASE_URL}${row.old_url}`;
    console.log(`  ${row.id}\n    old: ${row.old_url}\n    new: ${newUrl}`);
  }
  if (rows.length > 5) console.log(`  ... and ${rows.length - 5} more`);

  if (APPLY) {
    const result = await pool.query(
      `UPDATE ${table} SET ${column} = $1 || ${column}
       WHERE ${column} LIKE '/%' AND ${column} NOT ILIKE 'http%'`,
      [PUBLIC_BASE_URL]
    );
    console.log(`  APPLIED: ${result.rowCount} row(s) updated in ${table}.${column}`);
  }

  return { table, column, count: rows.length };
}

(async () => {
  console.log(APPLY ? '*** APPLY MODE — changes WILL be written ***' : 'DRY RUN — no changes will be made (set APPLY=true to write)');
  console.log(`Prefixing bare relative paths with: ${PUBLIC_BASE_URL}`);

  let total = 0;
  for (const target of TARGETS) {
    const { count } = await processTarget(target);
    total += count;
  }

  console.log(`\nTotal rows ${APPLY ? 'updated' : 'that would be updated'}: ${total}`);
  if (!APPLY) console.log('Nothing was changed. Re-run with APPLY=true node fix-relative-urls.js to apply.');

  await pool.end();
})().catch((err) => {
  console.error('Failed:', err);
  process.exit(1);
});
